const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden;color:var(--ink);font:12px/1.4 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",system-ui,sans-serif;font-variant-numeric:tabular-nums;--late:#CF4B34}\n.card *{box-sizing:border-box}\n.card>*:not(.ov){flex:1 1 0;min-height:0;min-width:0}\n.ov{flex:1 1 0;min-height:0;min-width:0;display:grid;gap:6px 8px;padding:10px}\nbutton{font:inherit;color:inherit;cursor:pointer}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.sum{grid-area:sum;display:flex;flex-direction:column;min-width:0}\n.lbl{font-size:10.5px;color:var(--muted);line-height:1.3}\n.big{font-size:22px;line-height:1.15;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub{font-size:10.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub.late{color:var(--late);font-weight:600}\n\n.flags{grid-area:flags;display:flex;gap:6px;min-width:0}\n.tile{flex:1 1 0;min-width:0;display:flex;flex-direction:column;padding:5px 7px;border-radius:9px;background:var(--soft);border:1px solid var(--line)}\n.t-l{font-size:10px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.t-v{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tile.late:not(.zero) .t-v,.tile.late:not(.zero) .t-l{color:var(--late)}\n.tile.zero .t-v{color:var(--muted);font-weight:400}\n\n.filters{grid-area:filters;display:flex;gap:5px;min-width:0;overflow-x:auto;scrollbar-width:none;align-items:center}\n.fchip{flex:none;height:24px;padding:0 9px;border-radius:12px;border:1px solid var(--line);background:transparent;font-size:11px;white-space:nowrap}\n.fchip[aria-pressed=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n\n.btn{height:32px;padding:0 14px;border-radius:16px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));font-weight:600;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.add{grid-area:add;align-self:start;display:inline-flex;align-items:center;justify-content:center;padding:0 12px}\n.add-i{font-size:15px;line-height:1}\n\n.list{grid-area:list;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding-right:1px}\n.none{color:var(--muted);font-size:11px;padding:8px 2px;line-height:1.5}\n.empty{display:flex;flex-direction:column;gap:6px;align-items:flex-start;padding:4px 2px}\n.empty b{font-size:13px}\n.empty span{color:var(--muted);font-size:11px;line-height:1.5}\n\n.row{flex:none;width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"name amt\" \"meta chip\" \"prog prog\";gap:1px 8px;align-items:center;text-align:left;padding:7px 9px 8px;border-radius:10px;border:1px solid var(--line);background:var(--soft)}\n.row.g3{opacity:.72}\n.r-name{grid-area:name;font-size:12.5px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.r-amt{grid-area:amt;font-size:12.5px;font-weight:700;white-space:nowrap;text-align:right}\n.r-amt small{display:none;font-size:10px;font-weight:400;color:var(--muted);margin-right:4px}\n.r-meta{grid-area:meta;display:flex;align-items:center;gap:5px;min-width:0;font-size:10.5px;color:var(--muted)}\n.r-proj{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tag{flex:none;font-size:9.5px;line-height:1.5;padding:0 5px;border-radius:6px;border:1px solid var(--line);white-space:nowrap}\n.tag.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.tag.off{color:var(--muted)}\n.prog{grid-area:prog;display:flex;flex-direction:column;gap:2px;margin-top:4px;min-width:0}\n.prog-t{display:none;font-size:10px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.bar{height:4px;border-radius:2px;background:var(--line);overflow:hidden}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:2px}\n.bar.g0 i{background:var(--late)}\n.bar.g3 i{background:var(--muted)}\n.chip{grid-area:chip;justify-self:end;font-size:10px;line-height:1.5;padding:0 6px;border-radius:8px;white-space:nowrap;border:1px solid var(--line);color:var(--muted)}\n.chip.g0{background:color-mix(in srgb,var(--late) 14%,transparent);border-color:var(--late);color:var(--late);font-weight:700}\n.chip.g1{background:var(--soft);border-color:var(--accent);color:var(--accent);font-weight:600}\n\n/* 3x3 */\n.card[data-size=\"3x3\"] .ov{grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr);grid-template-areas:\"sum add\" \"list list\";padding:8px;gap:6px}\n.card[data-size=\"3x3\"] .flags,.card[data-size=\"3x3\"] .filters{display:none}\n.card[data-size=\"3x3\"] .big{font-size:20px}\n.card[data-size=\"3x3\"] .add{width:32px;height:32px;padding:0;border-radius:50%}\n.card[data-size=\"3x3\"] .add-t{display:none}\n.card[data-size=\"3x3\"] .row{padding:5px 8px 6px}\n\n/* 6x3 */\n.card[data-size=\"6x3\"] .ov{grid-template-columns:130px minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr);grid-template-areas:\"sum filters\" \"flags list\" \"add list\";padding:9px;gap:6px 10px}\n.card[data-size=\"6x3\"] .flags{flex-direction:column;gap:3px}\n.card[data-size=\"6x3\"] .tile{flex-direction:row;justify-content:space-between;align-items:baseline;gap:4px;padding:2px 6px}\n.card[data-size=\"6x3\"] .t-v{font-size:11px;flex:none}\n.card[data-size=\"6x3\"] .add{align-self:end;width:100%}\n.card[data-size=\"6x3\"] .big{font-size:20px}\n.card[data-size=\"6x3\"] .sub{display:none}\n.card[data-size=\"6x3\"] .row{padding:5px 9px 6px;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) auto;grid-template-areas:\"name prog amt\" \"meta prog chip\"}\n.card[data-size=\"6x3\"] .prog{margin-top:0}\n.card[data-size=\"6x3\"] .prog-t{display:block}\n.card[data-size=\"6x3\"] .r-amt small{display:inline}\n\n/* 3x6 */\n.card[data-size=\"3x6\"] .ov{grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto auto minmax(0,1fr);grid-template-areas:\"sum add\" \"flags flags\" \"filters filters\" \"list list\";padding:9px}\n.card[data-size=\"3x6\"] .sub{display:none}\n.card[data-size=\"3x6\"] .tile{padding:4px 5px}\n.card[data-size=\"3x6\"] .t-l{font-size:9.5px}\n.card[data-size=\"3x6\"] .t-v{font-size:11.5px}\n.card[data-size=\"3x6\"] .fchip{padding:0 7px}\n\n/* 6x6 */\n.card[data-size=\"6x6\"] .ov{grid-template-columns:150px minmax(0,1fr) auto;grid-template-rows:auto auto minmax(0,1fr);grid-template-areas:\"sum flags add\" \"filters filters filters\" \"list list list\";padding:12px;gap:8px 12px}\n.card[data-size=\"6x6\"] .sub{display:none}\n.card[data-size=\"6x6\"] .big{font-size:24px}\n.card[data-size=\"6x6\"] .tile{padding:5px 9px}\n.card[data-size=\"6x6\"] .row{padding:8px 11px 9px;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) auto;grid-template-areas:\"name prog amt\" \"meta prog chip\"}\n.card[data-size=\"6x6\"] .prog{margin-top:0}\n.card[data-size=\"6x6\"] .prog-t{display:block}\n.card[data-size=\"6x6\"] .r-amt small{display:inline}\n\n/* detail */\n.dv{display:flex;flex-direction:column;gap:8px;min-width:0}\n.dv-top{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}\n.dv-proj{min-width:0;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dv .chip{flex:none}\n.dv-due{font-size:11px;color:var(--muted)}\n.dnums{display:grid;grid-template-columns:repeat(auto-fit,minmax(78px,1fr));gap:6px}\n.dn{display:flex;flex-direction:column;padding:6px 8px;border-radius:9px;background:var(--soft);border:1px solid var(--line);min-width:0}\n.dn-l{font-size:10px;color:var(--muted)}\n.dn-v{font-size:13px;white-space:nowrap}\n.dn.late .dn-v{color:var(--late)}\n.dn.got .dn-v{color:var(--accent)}\n.dv .bar{height:6px;border-radius:3px}\n.inv{display:flex;align-items:center;gap:7px;width:100%;height:34px;padding:0 10px;border-radius:10px;border:1px solid var(--line);background:var(--soft);text-align:left}\n.inv-k{width:18px;height:18px;line-height:16px;text-align:center;border-radius:50%;border:1px solid var(--muted);font-size:11px;flex:none}\n.inv.on .inv-k{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.inv-t{font-weight:600}\n.inv-h{margin-left:auto;font-size:10px;color:var(--muted)}\n.sec{display:flex;justify-content:space-between;align-items:baseline;font-weight:700;font-size:12px;margin-top:2px;padding-top:6px;border-top:1px solid var(--line)}\n.sec-n{font-weight:400;font-size:10.5px;color:var(--muted)}\n.pays{display:flex;flex-direction:column;gap:4px}\n.pay{display:flex;align-items:center;gap:8px;min-height:30px;padding:2px 4px 2px 8px;border-radius:8px;background:var(--soft);min-width:0}\n.pay-d{flex:none;font-size:11px;color:var(--muted);white-space:nowrap}\n.pay-n{flex:1 1 0;min-width:0;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pay-a{flex:none;white-space:nowrap}\n.x{flex:none;width:26px;height:26px;border:0;border-radius:50%;background:transparent;color:var(--muted);font-size:16px;line-height:1}\n.pay.ask{flex-wrap:wrap;padding:4px 6px}\n.pay-t{flex:1 1 100%;font-size:11px}\n.mini{height:26px;padding:0 10px;border-radius:13px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));font-size:11px}\n.mini.danger{border-color:var(--late);color:var(--late);font-weight:700}\n.err,.warn{padding:6px 8px;border-radius:8px;border:1px solid var(--late);background:color-mix(in srgb,var(--late) 12%,transparent);color:var(--late);font-size:11px;line-height:1.45;font-weight:600}\n";
var SOON_DAYS=7;
function cents(n){return Math.round(Number(n)*100);}
function fmt(c){
  var neg=c<0;c=Math.abs(c);
  var y=Math.floor(c/100),f=c%100;
  var s=String(y).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  if(f)s+='.'+(f<10?'0':'')+f;
  return (neg?'-':'')+'¥'+s;
}
function fmtShort(c){
  var y=Math.abs(c)/100;
  if(y>=10000){var w=Math.round(y/100)/100;return (c<0?'-':'')+'¥'+w+'万';}
  return fmt(c);
}
function dnum(s){
  var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s||''));
  if(!m)return null;
  return Math.round(Date.UTC(+m[1],+m[2]-1,+m[3])/86400000);
}
function mdate(s){
  var m=/^\d{4}-(\d{2})-(\d{2})$/.exec(String(s||''));
  return m?(+m[1])+'月'+(+m[2])+'日':String(s||'');
}
function sdate(s,t){
  return String(s).slice(0,4)===String(t).slice(0,4)?mdate(s):String(s);
}
function getItems(s){return s&&Array.isArray(s.items)?s.items:[];}
function paid(it){
  return (it.payments||[]).reduce(function(a,p){return a+cents(p.amount);},0);
}
function calc(it,today){
  var total=cents(it.amount),got=paid(it);
  var out=Math.max(0,total-got),settled=total>0&&got>=total;
  var dn=dnum(it.due),t=dnum(today);
  var days=(dn==null||t==null)?0:dn-t;
  var g=settled?3:(days<0?0:(days<=SOON_DAYS?1:2));
  var pct=total>0?Math.min(100,Math.floor(got*100/total)):0;
  return {it:it,total:total,got:got,out:out,settled:settled,days:days,g:g,pct:pct,over:Math.max(0,got-total)};
}
function statusText(c,today){
  if(c.settled)return '已收齐';
  if(c.g===0)return '逾期 '+(-c.days)+' 天';
  if(c.days===0)return '今天到期';
  if(c.g===1)return c.days+' 天后到期';
  return sdate(c.it.due,today)+'到期';
}
function sortCalc(a,b){
  if(a.g!==b.g)return a.g-b.g;
  if(a.g===3)return b.days-a.days;
  if(a.days!==b.days)return a.days-b.days;
  return b.out-a.out;
}
function passFilter(c,f){
  if(f==='open')return !c.settled;
  if(f==='done')return c.settled;
  if(f==='noinv')return !c.it.invoiced;
  return true;
}
function baseState(s){return (s&&typeof s==='object')?s:{};}
function patchItem(s,id,fn){
  return Object.assign({},baseState(s),{items:getItems(s).map(function(x){return x.id===id?fn(x):x;})});
}
function round2(n){return Math.round(n*100)/100;}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size,editor,panel}=ctx;
  const today=day();
  if(!ui.view)ui.view='list';
  if(!ui.filter)ui.filter='all';
  const h=(t,a,...c)=>el(t,a||{},...c.flat().filter(x=>x!==null&&x!==undefined&&x!==false));
  const go=p=>{Object.assign(ui,p);redraw();};
  const keep=p=>Object.assign({view:'list',id:null,filter:ui.filter,draft:null,confirm:null,err:null},p);
  const run=p=>Promise.resolve(p).catch(()=>{ui.err='保存失败，请重试';redraw();});
  const items=getItems(state);
  const find=id=>items.find(x=>x.id===id);
  const toList=()=>go({view:'list',id:null,draft:null,confirm:null,err:null});
  const toDetail=id=>go({view:'detail',id:id,draft:null,confirm:null,err:null});

  const openNew=()=>go({view:'form',id:null,confirm:null,err:null,
    draft:{client:'',project:'',amount:'',due:'',invoiced:false,firstAmt:'',firstDate:''}});
  const openEdit=it=>go({view:'form',id:it.id,confirm:null,err:null,
    draft:{client:it.client||'',project:it.project||'',amount:String(cents(it.amount)/100),due:it.due||'',invoiced:!!it.invoiced}});
  const openPay=it=>go({view:'pay',id:it.id,confirm:null,err:null,
    draft:{amount:'',date:today,note:''}});

  const recFields=[
    {key:'client',label:'客户',required:true,placeholder:'客户名称'},
    {key:'project',label:'项目',placeholder:'项目名称'},
    {key:'amount',label:'约定金额（元）',type:'number',required:true,min:0.01,step:'any',placeholder:'0.00'},
    {key:'due',label:'约定到账日期',type:'date',required:true},
    {key:'invoiced',label:'已开票',type:'checkbox'}
  ];
  const firstFields=[
    {key:'firstAmt',label:'已经收到多少（元，没收到可不填）',type:'number',min:0,step:'any',placeholder:'0.00'},
    {key:'firstDate',label:'这笔的收款日期（不填按今天）',type:'date'}
  ];

  function checkRec(v){
    if(!String(v.client||'').trim())return '请填写客户名称';
    const amt=Number(v.amount);
    if(!(amt>0)||amt>=1e11)return '约定金额须大于 0';
    if(dnum(v.due)==null)return '请选择约定到账日期';
    return '';
  }

  function recordForm(){
    const editing=ui.id?find(ui.id):null;
    if(ui.id&&!editing){ui.view='list';ui.id=null;return null;}
    const isNew=!editing;
    return editor({
      title:isNew?'新增应收':'编辑应收',
      draft:ui.draft,
      fields:isNew?recFields.concat(firstFields):recFields,
      submitLabel:isNew?'保存':'保存修改',
      onBack:()=>isNew?toList():toDetail(editing.id),
      onSave:v=>{
        const e=checkRec(v);
        if(e)return e;
        const fields={
          client:String(v.client).trim(),
          project:String(v.project||'').trim(),
          amount:round2(Number(v.amount)),
          due:v.due,
          invoiced:!!v.invoiced
        };
        if(!isNew){
          return commit(s=>patchItem(s,editing.id,x=>Object.assign({},x,fields)),keep({view:'detail',id:editing.id}));
        }
        const rec=Object.assign({id:uid(),payments:[]},fields);
        const fa=String(v.firstAmt==null?'':v.firstAmt).trim();
        if(fa!==''){
          const n=Number(fa);
          if(!(n>=0)||n>=1e11)return '已收金额不能为负数';
          if(n>0){
            const d=v.firstDate||today;
            if(dnum(d)==null)return '收款日期不正确';
            if(dnum(d)>dnum(today))return '收款日期不能晚于今天';
            rec.payments.push({id:uid(),date:d,amount:round2(n),note:''});
          }
        }
        return commit(s=>Object.assign({},baseState(s),{items:[rec].concat(getItems(s))}),keep({view:'detail',id:rec.id,filter:'all'}));
      }
    });
  }

  function payForm(){
    const it=find(ui.id);
    if(!it){ui.view='list';ui.id=null;return null;}
    const c=calc(it,today);
    return editor({
      title:'记一笔收款 · '+it.client,
      draft:ui.draft,
      fields:[
        {key:'amount',label:'本次收到（元）',type:'number',required:true,min:0.01,step:'any',
          placeholder:c.settled?'已收齐，可补记':'还差 '+fmt(c.out)},
        {key:'date',label:'到账日期',type:'date',required:true},
        {key:'note',label:'备注（如：首期款、尾款）',placeholder:'可不填'}
      ],
      submitLabel:'保存收款',
      onBack:()=>toDetail(it.id),
      onSave:v=>{
        const amt=Number(v.amount);
        if(!(amt>0)||amt>=1e11)return '收款金额须大于 0';
        const d=String(v.date||'');
        if(dnum(d)==null)return '请选择到账日期';
        if(dnum(d)>dnum(today))return '到账日期不能晚于今天';
        const p={id:uid(),date:d,amount:round2(amt),note:String(v.note||'').trim()};
        return commit(s=>patchItem(s,it.id,x=>Object.assign({},x,{payments:(x.payments||[]).concat([p])})),
          keep({view:'detail',id:it.id}));
      }
    });
  }


  function progBar(c){
    const i=h('i');
    i.style.width=c.pct+'%';
    return h('div',{class:'bar g'+c.g},i);
  }

  function detailView(it){
    const c=calc(it,today);
    const pays=(it.payments||[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));
    const cell=(l,v,cls)=>h('div',{class:'dn '+(cls||'')},h('span',{class:'dn-l'},l),h('b',{class:'dn-v'},v));
    const delPay=p=>{
      ui.confirm=null;
      run(update(s=>patchItem(s,it.id,x=>Object.assign({},x,{payments:(x.payments||[]).filter(q=>q.id!==p.id)}))));
    };
    const payRows=pays.map(p=>{
      if(ui.confirm==='pay:'+p.id){
        return h('div',{class:'pay ask'},
          h('span',{class:'pay-t'},'删除这笔 '+fmt(cents(p.amount))+'？'),
          h('button',{type:'button',class:'mini danger',onclick:()=>delPay(p)},'确认删除'),
          h('button',{type:'button',class:'mini',onclick:()=>go({confirm:null})},'取消'));
      }
      return h('div',{class:'pay'},
        h('span',{class:'pay-d'},sdate(p.date,today)),
        h('span',{class:'pay-n'},p.note||''),
        h('b',{class:'pay-a'},fmt(cents(p.amount))),
        h('button',{type:'button',class:'x','aria-label':'删除这笔收款',onclick:()=>go({confirm:'pay:'+p.id})},'×'));
    });
    const toggleInv=()=>{
      ui.err=null;
      run(update(s=>patchItem(s,it.id,x=>Object.assign({},x,{invoiced:!x.invoiced}))));
    };
    const body=h('div',{class:'dv'},
      ui.err?h('div',{class:'err',role:'alert'},'⚠ '+ui.err):null,
      ui.confirm==='del'?h('div',{class:'warn',role:'alert'},'⚠ 确定删除这笔应收'+(pays.length?'及 '+pays.length+' 条收款记录':'')+'？删除后无法恢复。'):null,
      h('div',{class:'dv-top'},
        h('span',{class:'dv-proj'},it.project||'（未填项目）'),
